export type CircuitState = 'CLOSED' | 'OPEN' | 'HALF_OPEN';

export interface CircuitBreakerOptions {
  failureThreshold?: number;
  resetTimeoutMs?: number;
}

export class ApiError extends Error {
  readonly statusCode: number;

  constructor(message: string, statusCode: number) {
    super(message);
    this.name = 'ApiError';
    this.statusCode = statusCode;
    Object.setPrototypeOf(this, ApiError.prototype);
  }
}

export class CircuitOpenError extends ApiError {
  constructor(message = 'Circuit breaker is OPEN') {
    super(message, 503);
    this.name = 'CircuitOpenError';
    Object.setPrototypeOf(this, CircuitOpenError.prototype);
  }
}

export class TimeoutError extends ApiError {
  constructor(message = 'Request timed out') {
    super(message, 408);
    this.name = 'TimeoutError';
    Object.setPrototypeOf(this, TimeoutError.prototype);
  }
}

export class CircuitBreaker {
  private readonly failureThreshold: number;
  private readonly resetTimeoutMs: number;
  private currentState: CircuitState = 'CLOSED';
  private failureCount = 0;
  private successCount = 0;
  private openedAt = 0;

  constructor(options: CircuitBreakerOptions = {}) {
    const threshold = options.failureThreshold ?? 5;
    const reset = options.resetTimeoutMs ?? 30_000;
    if (!Number.isFinite(threshold) || threshold < 1) {
      throw new RangeError('failureThreshold must be a finite number >= 1');
    }
    if (!Number.isFinite(reset) || reset < 0) {
      throw new RangeError('resetTimeoutMs must be a finite number >= 0');
    }
    this.failureThreshold = Math.floor(threshold);
    this.resetTimeoutMs = reset;
  }

  get state(): CircuitState {
    return this.getState();
  }

  getState(): CircuitState {
    if (this.currentState === 'OPEN' && Date.now() - this.openedAt >= this.resetTimeoutMs) {
      this.currentState = 'HALF_OPEN';
      this.successCount = 0;
    }
    return this.currentState;
  }

  get failures(): number {
    return this.failureCount;
  }

  recordSuccess(): void {
    this.failureCount = 0;
    this.successCount += 1;
    this.currentState = 'CLOSED';
  }

  recordFailure(): void {
    const state = this.getState();
    if (state === 'HALF_OPEN') {
      this.trip();
      return;
    }
    this.failureCount += 1;
    if (this.failureCount >= this.failureThreshold) this.trip();
  }

  reset(): void {
    this.currentState = 'CLOSED';
    this.failureCount = 0;
    this.successCount = 0;
    this.openedAt = 0;
  }

  async execute<T>(action: () => Promise<T>): Promise<T> {
    if (typeof action !== 'function') throw new TypeError('action must be a function');
    if (this.getState() === 'OPEN') {
      const waitMs = Math.max(0, this.resetTimeoutMs - (Date.now() - this.openedAt));
      throw new CircuitOpenError(`Circuit breaker is OPEN; retry in ${waitMs}ms`);
    }
    try {
      const result = await action();
      this.recordSuccess();
      return result;
    } catch (err) {
      this.recordFailure();
      throw err;
    }
  }

  private trip(): void {
    this.currentState = 'OPEN';
    this.openedAt = Date.now();
    this.failureCount = this.failureThreshold;
  }
}

export interface RequestOptions {
  timeoutMs?: number;
  headers?: Record<string, string>;
}

type FetchLike = (url: string, init: { method: string; headers: Record<string, string>; signal?: AbortSignal }) => Promise<{
  ok: boolean;
  status: number;
  statusText?: string;
  json: () => Promise<unknown>;
  text?: () => Promise<string>;
}>;

export class ResilientHttpClient {
  private readonly breaker: CircuitBreaker;
  private readonly fetchImpl: FetchLike;
  private readonly cache = new Map<string, { value: unknown; expiresAt: number }>();

  constructor(circuitBreaker?: CircuitBreaker, fetchImpl?: FetchLike) {
    this.breaker = circuitBreaker ?? new CircuitBreaker();
    const resolved = fetchImpl ?? (globalThis as { fetch?: FetchLike }).fetch;
    if (typeof resolved !== 'function') {
      throw new Error('No fetch implementation available; provide one explicitly');
    }
    this.fetchImpl = resolved.bind(globalThis) as FetchLike;
  }

  get circuitState(): CircuitState {
    return this.breaker.getState();
  }

  async get<T>(url: string, options: RequestOptions = {}): Promise<T> {
    if (typeof url !== 'string' || url.trim().length === 0) {
      throw new TypeError('url must be a non-empty string');
    }
    const timeoutMs = options.timeoutMs ?? 10_000;
    if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) {
      throw new RangeError('timeoutMs must be a finite number > 0');
    }
    const headers: Record<string, string> = { Accept: 'application/json', ...(options.headers ?? {}) };

    const cached = this.cache.get(url);
    if (cached && cached.expiresAt > Date.now()) return cached.value as T;

    return this.breaker.execute<T>(async () => {
      const controller = typeof AbortController === 'function' ? new AbortController() : undefined;
      let timedOut = false;
      const timer = setTimeout(() => {
        timedOut = true;
        controller?.abort();
      }, timeoutMs);
      try {
        const response = await this.fetchImpl(url, { method: 'GET', headers, signal: controller?.signal });
        if (!response.ok) {
          let detail = response.statusText ?? '';
          if (typeof response.text === 'function') {
            try {
              detail = (await response.text()) || detail;
            } catch {
              /* keep statusText */
            }
          }
          throw new ApiError(`GET ${url} failed with status ${response.status}${detail ? `: ${detail}` : ''}`, response.status);
        }
        const body = (await response.json()) as T;
        this.cache.set(url, { value: body, expiresAt: Date.now() + 1000 });
        return body;
      } catch (err) {
        if (timedOut) throw new TimeoutError(`GET ${url} timed out after ${timeoutMs}ms`);
        if (err instanceof ApiError) throw err;
        throw new ApiError(`GET ${url} failed: ${err instanceof Error ? err.message : String(err)}`, 0);
      } finally {
        clearTimeout(timer);
      }
    });
  }

  clearCache(): void {
    this.cache.clear();
  }
}

