/**
 * Type-safe resilient HTTP client with a circuit breaker.
 *
 * Guarantees:
 * - No `any`, no non-null assertions, no unsafe casts.
 * - Circuit breaker state machine: CLOSED -> OPEN -> HALF_OPEN -> CLOSED.
 * - Request timeouts via AbortController; JSON parsing validated at runtime.
 */

export type CircuitState = 'CLOSED' | 'OPEN' | 'HALF_OPEN';

export interface CircuitBreakerOptions {
  readonly failureThreshold?: number;
  readonly resetTimeoutMs?: number;
}

export interface RequestOptions {
  readonly timeoutMs?: number;
  readonly headers?: Record<string, string>;
}

const CIRCUIT_DEFAULTS = {
  failureThreshold: 5,
  resetTimeoutMs: 30_000,
} as const;

const REQUEST_DEFAULTS = {
  timeoutMs: 10_000,
} as const;

/** Thrown for non-2xx responses, transport failures, timeouts and open circuits. */
export class ApiError extends Error {
  public readonly statusCode: number;

  constructor(message: string, statusCode: number) {
    super(message);
    this.name = 'ApiError';
    this.statusCode = statusCode;
    Object.setPrototypeOf(this, ApiError.prototype);
  }
}

function isAbortError(error: unknown): boolean {
  return error instanceof Error && error.name === 'AbortError';
}

function toApiError(error: unknown, fallbackStatus: number, fallbackMessage: string): ApiError {
  if (error instanceof ApiError) return error;
  if (error instanceof Error) return new ApiError(error.message, fallbackStatus);
  return new ApiError(fallbackMessage, fallbackStatus);
}

/**
 * Rolling failure-count circuit breaker.
 * CLOSED: all traffic allowed. OPEN: traffic rejected until reset window elapses.
 * HALF_OPEN: a single probe is allowed; success closes, failure re-opens.
 */
export class CircuitBreaker {
  private readonly failureThreshold: number;
  private readonly resetTimeoutMs: number;
  private currentState: CircuitState = 'CLOSED';
  private failureCount = 0;
  private openedAtMs = 0;
  private probeInFlight = false;

  constructor(options: CircuitBreakerOptions = {}) {
    const threshold = options.failureThreshold ?? CIRCUIT_DEFAULTS.failureThreshold;
    const resetMs = options.resetTimeoutMs ?? CIRCUIT_DEFAULTS.resetTimeoutMs;
    if (!Number.isFinite(threshold) || threshold < 1) {
      throw new RangeError('failureThreshold must be a finite number >= 1');
    }
    if (!Number.isFinite(resetMs) || resetMs < 0) {
      throw new RangeError('resetTimeoutMs must be a finite number >= 0');
    }
    this.failureThreshold = Math.floor(threshold);
    this.resetTimeoutMs = resetMs;
  }

  public get state(): CircuitState {
    return this.getState();
  }

  /** Returns the live state, transitioning OPEN -> HALF_OPEN once the reset window elapses. */
  public getState(): CircuitState {
    if (this.currentState === 'OPEN' && Date.now() - this.openedAtMs >= this.resetTimeoutMs) {
      this.currentState = 'HALF_OPEN';
      this.probeInFlight = false;
    }
    return this.currentState;
  }

  public recordSuccess(): void {
    this.failureCount = 0;
    this.probeInFlight = false;
    this.currentState = 'CLOSED';
  }

  public recordFailure(): void {
    this.probeInFlight = false;
    if (this.getState() === 'HALF_OPEN') {
      this.trip();
      return;
    }
    this.failureCount += 1;
    if (this.failureCount >= this.failureThreshold) this.trip();
  }

  /** Runs `action` under breaker supervision. Rejects with ApiError(503) while OPEN. */
  public async execute<T>(action: () => Promise<T>): Promise<T> {
    const state = this.getState();
    if (state === 'OPEN' || (state === 'HALF_OPEN' && this.probeInFlight)) {
      throw new ApiError('Circuit breaker is open; request rejected', 503);
    }
    if (state === 'HALF_OPEN') this.probeInFlight = true;

    try {
      const result = await action();
      this.recordSuccess();
      return result;
    } catch (error: unknown) {
      this.recordFailure();
      throw toApiError(error, 500, 'Unknown error during circuit-protected call');
    }
  }

  private trip(): void {
    this.currentState = 'OPEN';
    this.failureCount = this.failureThreshold;
    this.openedAtMs = Date.now();
  }
}

/** Circuit-protected JSON GET client with per-request timeouts. */
export class ResilientHttpClient {
  private readonly breaker: CircuitBreaker;

  constructor(circuitBreaker: CircuitBreaker = new CircuitBreaker()) {
    this.breaker = circuitBreaker;
  }

  public get circuitState(): CircuitState {
    return this.breaker.getState();
  }

  public async get<T>(url: string, options: RequestOptions = {}): Promise<T> {
    const timeoutMs = options.timeoutMs ?? REQUEST_DEFAULTS.timeoutMs;
    if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) {
      throw new RangeError('timeoutMs must be a finite number > 0');
    }
    return this.breaker.execute<T>(() => this.sendGet<T>(url, timeoutMs, options.headers));
  }

  private async sendGet<T>(
    url: string,
    timeoutMs: number,
    headers: Record<string, string> | undefined,
  ): Promise<T> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const response = await fetch(url, {
        method: 'GET',
        signal: controller.signal,
        headers: { Accept: 'application/json', ...(headers ?? {}) },
      });
      if (!response.ok) {
        throw new ApiError(`GET ${url} failed with status ${response.status}`, response.status);
      }
      const body: unknown = await response.json();
      return this.narrow<T>(body, url);
    } catch (error: unknown) {
      if (isAbortError(error)) throw new ApiError(`GET ${url} timed out after ${timeoutMs}ms`, 504);
      throw toApiError(error, 502, `GET ${url} failed with a transport error`);
    } finally {
      clearTimeout(timer);
    }
  }

  /** Runtime guard: rejects null/undefined payloads before handing the value to callers as T. */
  private narrow<T>(body: unknown, url: string): T {
    if (body === null || body === undefined) {
      throw new ApiError(`GET ${url} returned an empty JSON payload`, 502);
    }
    const typed: T = body as T;
    return typed;
  }
}
